{
  "technical_and_design_decisions": [
    "Leverage Spring YARN framework for HDFS and ResourceManager interactions to minimize boilerplate.",
    "Implement an asynchronous task executor using Spring's @Async or a dedicated TaskExecutor to queue deploy operations.",
    "Refactor the existing ModuleLauncher to delegate to Spring Boot's JarLauncher API to eliminate duplicate functionality.",
    "Use Spring Cloud Data Flow deployment properties to pass YARN-specific configurations (queues, priorities, memory, CPU) for multiple app instances.",
    "Design a uniform external library resolution mechanism that dynamically adds resolved JARs to the Boot loader classpath."
  ],
  "assumptions": [
    "The developer has access to a configured Hadoop/YARN test environment for integration testing.",
    "The existing Spring Cloud Data Flow codebase is available, modular, and well-structured.",
    "The acronyms 's-c-d' and 's-c-s' refer to Spring Cloud Data Flow and Spring Cloud Stream, respectively.",
    "The developer is highly proficient in Java, Spring Boot, Spring YARN, and Hadoop ecosystems.",
    "No external UI changes are required; all interactions are via shell commands and deployment properties."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Design and Architecture",
      "activity_description": "Analyze requirements, design the architecture for async YARN deployment, multiple app instances, and external library resolution.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A2",
      "activity_name": "HDFS Auto-deployment & Manifest Orchestration (U1)",
      "activity_description": "Implement support to deploy YARN App into HDFS automatically and orchestrate overall deployment using a manifest.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A3",
      "activity_name": "ResourceManager REST-API Integration (U2)",
      "activity_description": "Implement negotiation with ResourceManager REST-APIs to deploy modules by groups, taking into account app specifics like appType and appName.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A4",
      "activity_name": "Multiple App Instances Support (U3)",
      "activity_description": "Implement support for multiple app instances using deployment properties to define different queues, priorities, and resource reservations.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A5",
      "activity_name": "Asynchronous Deployer (U4)",
      "activity_description": "Refactor the deployer to work asynchronously, allowing the shell to return quickly and queue deploy operations within YARN as tasks.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A6",
      "activity_name": "External Library Resolution & Boot Loader Integration (U5, U8)",
      "activity_description": "Experiment, resolve, and add module dependent JARs to the Boot loader in a uniform way to handle external libraries required by OOTB modules.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A7",
      "activity_name": "Refactor ModuleLauncher (U6)",
      "activity_description": "Refactor the current ModuleLauncher contract with Boot's JarLauncher API to remove duplicate functionality.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A8",
      "activity_name": "Documentation and Test Cases (U7)",
      "activity_description": "Complete documentation and test-cases on resolving and adding JARs to the Boot loader to serve as a reference for porting modules with external dependencies.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A9",
      "activity_name": "Integration Testing & QA",
      "activity_description": "Perform end-to-end integration testing of all new features within the YARN environment and ensure overall system stability.",
      "most_likely_effort": 4
    }
  ],
  "reported_total": {
    "most_likely_effort": 37
  }
}

